  \node[draw,rounded corners] (no) at (3,1.75) {$Q=\{S:a\notin S\}$};
  \node[draw,rounded corners] (left) at (-3,0.35) {$[A']^k$};
  \node[draw,rounded corners] (right) at (3,0.35) {$[A']^{k+1}$};
  \draw[->] (all) -- (yes);
